import{_ as a,o as n,c as r,j as l,a as t,a2 as o}from"./chunks/framework.BkKoiSIN.js";const b=JSON.parse('{"title":"评测与实验设计","description":"将质量、可靠性和服务成本放在同一个可复核的实验中。","frontmatter":{"title":"评测与实验设计","description":"将质量、可靠性和服务成本放在同一个可复核的实验中。","kind":"overview","status":"published"},"headers":[],"relativePath":"evaluation/index.md","filePath":"evaluation/index.md"}'),i={name:"evaluation/index.md"};function d(s,e,u,h,c,p){return n(),r("div",null,[...e[0]||(e[0]=[l("h1",{id:"评测与实验设计",tabindex:"-1"},[t("评测与实验设计 "),l("a",{class:"header-anchor",href:"#评测与实验设计","aria-label":'Permalink to "评测与实验设计"'},"​")],-1),l("p",null,"评测从第一轮小模型实验开始，贯穿推理、SFT、偏好优化与应用。这里组织待学习的方法与验收要求；发布导航不代表已经完成个人实测。一次漂亮回答、一次loss下降或一次吞吐提升，都需要通过固定任务和合理对照检验。",-1),l("h2",{id:"先把比较问题写清楚",tabindex:"-1"},[t("先把比较问题写清楚 "),l("a",{class:"header-anchor",href:"#先把比较问题写清楚","aria-label":'Permalink to "先把比较问题写清楚"'},"​")],-1),l("div",{class:"reading-table",role:"group","aria-label":"表格",tabindex:"0"},[l("table",null,[l("thead",null,[l("tr",null,[l("th",null,"层次"),l("th",null,"需要回答的问题"),l("th",null,"最小证据")])]),l("tbody",null,[l("tr",null,[l("td",null,"能力"),l("td",null,"模型是否更会完成目标任务？"),l("td",null,"同一保留集的逐题输出、评分规则与误差分析")]),l("tr",null,[l("td",null,"稳健性"),l("td",null,"提示顺序、措辞、长度或证据位置变化会怎样？"),l("td",null,"事先约定的扰动与分组结果")]),l("tr",null,[l("td",null,"可靠性"),l("td",null,"超时、取消、格式错误、工具失败后怎样结束？"),l("td",null,"成功分母、失败分类、状态与资源释放记录")]),l("tr",null,[l("td",null,"服务"),l("td",null,"在给定负载下是否满足延迟目标？"),l("td",null,"负载模型、TTFT/TPOT分布、吞吐和失败率")]),l("tr",null,[l("td",null,"成本"),l("td",null,"达到同等质量需要多少资源？"),l("td",null,"模型/硬件/精度、token量、峰值内存与费用口径")])])])],-1),o('<p>这种多指标视角参考<a href="https://arxiv.org/abs/2211.09110v2" target="_blank" rel="noreferrer">HELM v2</a>；下面的实验规模与验收方式是本站学习设计，不是论文结果的复现声明。</p><h2 id="一个共同实验协议" tabindex="-1">一个共同实验协议 <a class="header-anchor" href="#一个共同实验协议" aria-label="Permalink to &quot;一个共同实验协议&quot;">​</a></h2><ol><li><strong>实验前</strong>写假设、基线、唯一主变量和停止条件。例如“同模型同数据下，仅改变量化精度，观察内存收益与错误类型”。</li><li><strong>固定保留集</strong>并记录来源、许可、样本ID、划分和散列；训练、偏好构造、提示调参都不能回看最终测试答案。同源文档、近重复和同一问题的改写应一起划分。</li><li><strong>保存实际输入</strong>：chat template、system指令、完整生成配置、截断、停止词和答案提取器都属于实验条件。</li><li><strong>逐样本记录</strong>输出、评分、耗时、输入输出token、失败原因；先确认链路正确，再扩大样本。</li><li><strong>做成对比较</strong>：同一题比较基线与候选；报告样本数、分组、重复和不确定性，不只展示平均分。</li><li><strong>解释退化</strong>：把收益、损失、无效改动和未覆盖场景一起写进结论。最终测试集若用于反复选方案，就需要新的独立验收集。</li></ol><p>可从<a href="/evaluation/quality-systems">质量与服务成本实验</a>落实为第一份协议，再复用于<a href="/projects/serving-lab">推理项目</a>、<a href="/projects/finetuning-lab">SFT项目</a>和<a href="/projects/post-training-lab">偏好优化项目</a>。</p><p>对输入扰动、证据不足、过度拒答、工具权限与解释性假设，继续进入<a href="/evaluation/robustness-safety">鲁棒性、安全与可解释性</a>。这些是不同的可测行为，不用一个总分代表全部可靠性。</p><h2 id="工具需要掌握到哪一层" tabindex="-1">工具需要掌握到哪一层 <a class="header-anchor" href="#工具需要掌握到哪一层" aria-label="Permalink to &quot;工具需要掌握到哪一层&quot;">​</a></h2><p>目标是能解释“数据怎样变成分数”，随后才是熟练运行框架。</p><ul><li><strong>任务层</strong>：数据加载、样本划分、提示构造、few-shot样本与污染检查。</li><li><strong>模型层</strong>：区分生成任务与候选答案log-likelihood评分；确认模型与tokenizer版本、模板和特殊token。</li><li><strong>评分层</strong>：理解答案提取、规范化、聚合与失败样本处理；不能只相信一个最终数字。</li><li><strong>执行层</strong>：缓存是否会复用旧配置结果、超时如何计入、原始输出能否重放。</li></ul><p>可选入口为<a href="https://github.com/EleutherAI/lm-evaluation-harness/tree/d6de81643928d653435c431bae19945d41d32520" target="_blank" rel="noreferrer">EleutherAI harness固定版本</a>。先读一个任务定义与对应样本日志；该版本文档已说明CLI子命令调整，执行前核对固定版本的help，不混用旧教程。工具可复用，评测设计与结论仍需自己解释。</p><h2 id="四种证据分别验收" tabindex="-1">四种证据分别验收 <a class="header-anchor" href="#四种证据分别验收" aria-label="Permalink to &quot;四种证据分别验收&quot;">​</a></h2>',10),l("div",{class:"reading-table",role:"group","aria-label":"表格",tabindex:"0"},[l("table",null,[l("thead",null,[l("tr",null,[l("th",null,"证据"),l("th",null,"能支持什么"),l("th",null,"不能替代什么")])]),l("tbody",null,[l("tr",null,[l("td",null,"机制分析"),l("td",null,"公式、假设、复杂度和反例"),l("td",null,"实际模型质量或硬件提速")]),l("tr",null,[l("td",null,"源码追踪"),l("td",null,"固定commit上的数据流与执行路径"),l("td",null,"代码未覆盖配置的行为")]),l("tr",null,[l("td",null,"CPU机制实验"),l("td",null,"小张量、采样性质、评分和状态机"),l("td",null,"GPU通信、内核与大模型吞吐")]),l("tr",null,[l("td",null,"真实硬件实验"),l("td",null,"指定模型、硬件、版本和负载的结果"),l("td",null,"其他规模、平台和服务环境的结论")])])])],-1),l("p",null,[t("所有实验保留本人解释、AI协作范围、代码版本与未解决问题。公开报告只使用可公开的数据和配置，具体写法见"),l("a",{href:"/writing/"},"博文方法"),t("。")],-1),l("h2",{id:"资料核验",tabindex:"-1"},[t("资料核验 "),l("a",{class:"header-anchor",href:"#资料核验","aria-label":'Permalink to "资料核验"'},"​")],-1),l("p",null,[t("核验日期：2026-11-16。HELM使用论文v2；harness固定commit为"),l("code",null,"d6de81643928d653435c431bae19945d41d32520"),t("。以上链接支持方法或工具入口，不表示本站已运行这些基准或完成源码复现。")],-1)])])}const f=a(i,[["render",d]]);export{b as __pageData,f as default};
